#!/usr/bin/env sh
# fetch Transport for NSW — Timetables Complete GTFS (all Greater Sydney operators: Sydney Trains, buses, ferries, light rail, Metro) (AU) GTFS -> gtfs.zip. Regenerated by build_repo.py.
URL="https://api.transport.nsw.gov.au/v1/gtfs/schedule/{mode}"
DIR="$(CDPATH= cd "$(dirname "$0")" && pwd)"
echo "GET $URL"
curl -fSL --retry 3 --max-time 300 -o "$DIR/gtfs.zip" "$URL" || { echo "download failed"; exit 1; }
unzip -l "$DIR/gtfs.zip" 2>/dev/null | grep -q stops.txt || { echo "not valid GTFS (no stops.txt)"; exit 2; }
echo "ok: $DIR/gtfs.zip"
